function CatHouseEntry:SwitchAngle()
    local Duration = 0.3
    ---切换镜头的按钮的逻辑
    local sequence = DOTween.Sequence()
    if self.viewPort == 1 then
        ---切到第二个镜头参数
        local transform = self.mCamera.transform
        self.viewPort = 2
        local t = ViewPorts[self.viewPort]
        sequence:Append(transform:DOMove(t.pos, Duration))
        sequence:Join(transform:DORotate(t.rot, Duration))
        sequence:PlayForward()
    else
        local transform = self.mCamera.transform
        self.viewPort = 1
        local t = ViewPorts[self.viewPort]
        sequence:Append(transform:DOMove(t.pos, Duration))
        sequence:Join(transform:DORotate(t.rot, Duration))
        sequence:PlayForward()
    end
end

