function CatHouseEntry:OnFocus(focus)
    kTool.SetActive(self.controller.gameObject, checkBool(focus))
    --if focus then
    --    GameUtils.UpdateNavBarShowGoods({ self.hatchConsumeId, self.rallyGoodsId }, true)
    --else
