        local sceneManagement = SceneManagement:GetInstance()
        sceneManagement:SetActive(Constants.IdSceneSetting21, true)
        local sceneInstance = sceneManagement:GetSceneInstance(Constants.IdSceneSetting25)
        if sceneInstance then
            local catGo = sceneInstance:GetCacheObjectByName("CatModel")
            if not isNull(catGo) then
                kTool.DestroyGameObjectChildren(catGo)
            end
        end

        local component = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.BackpackComponent)
        local t = component:GetBlindBoxData()
        kTool.SetActive(self.BtnBlindbox, table.count(t) > 0)

        local go = GameUtils.GetRedPointGo(self.BtnBlindbox)
        if go then
            kTool.SetActive(go, table.count(t) > 0)
        end

        if not self.isInit then
            self:FreshBtnCultivationAni()
        else
            self.isInit = false
        end
    end
end
function CatHouseEntry:OnHide()
    local coWait = CoWait.Start():Coroutine(
            util.cs_generator(
                    function()
                        if not isNull(self._behaviourAction) then
                            self._behaviourAction.LateUpdateAction = nil
                            self._behaviourAction = nil
                        end
                    end
            )
    )
    return coWait
end

function CatHouseEntry:OnInitialize()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        --coroutine.yield(CatHouseMgr:GetInstance():Initialize())
        self:RegRedPoint()
        local behaviourAction = kTool.GetOrAddComponent(self.controller.gameObject, typeof(BehaviourAction))
        if behaviourAction then
            behaviourAction.LateUpdateAction = function()
                self:Update()
            end
            self._behaviourAction = behaviourAction
        end
        self.touchEventDetectionUtils = TouchEventDetectionUtils.New(
                {
                    touchScreenCallback = Bind(self, self.GetRayCastCatAction),
                    showPressCallback = Bind(self, self.SetLongTapSignShowState),
                    pressCallback = Bind(self, self.ShowCatInfoTip),
                    touchEndCallback = Bind(self, self.ActionAtTouchEnd),
                }
        )

    end))
    return coWait
end

function CatHouseEntry:GetRayCastCatAction()
    local ray = self.mCamera:ScreenPointToRay(Input.mousePosition)
    local bool = Physics.Raycast(ray)
    if bool then
        local rayCastHit = kTool.GetRaycastHitByTouch(ray)
        local cats = CatHouseMgr.cats
        for i = 1, #cats do
            local catAI = cats[i]
            if not IsNull(catAI) then
                if catAI.transform == rayCastHit.transform then
                    self.longTapCatGo = catAI
                    return true
                end
            end
        end
        return false
    end
end

