function CatHouseEntry:ShowCatInfoTip()
    print('--ShowCatInfoTip->>>---处理猫的移动的逻辑')
    if self.longTapCatGo then
        self.longTapCatGo.Env:StartDrag()
    end
end

function CatHouseEntry:OnMoveEvent()
    if self.isMoving and self.longTapCatGo and self.mCamera then
        local v = Input.mousePosition
        --local p = vector3(v.x, v.y, self.touchPos.z)
        local position3D = self.mCamera.transform:InverseTransformPoint(self.longTapCatGo.transform.position)
        local p = vector3(v.x, v.y, position3D.z)
        local position = self.mCamera:ScreenToWorldPoint(p)
        self.longTapCatGo.Env:OnDragging(position)
        local offsetY = self.longTapCatGo.Env:GetDraggingOffset()
        self:SetLongTapSignPos(true, offsetY)
    end
end

function CatHouseEntry:GetCharacterUIPositionByV3(offsetPosition)
    local uiCamera = UIModule.RootCanvas.defaultCamera
    local vec3 = self.mCamera:WorldToViewportPoint(offsetPosition)
    return uiCamera:ViewportToWorldPoint(vec3)
end

function CatHouseEntry:SetLongTapSignPos(isShow, offsetY)
    local _GetV3 = function(roleView)
        local goTrans = roleView.transform
        local y = goTrans.position.y + offsetY
        return self:GetCharacterUIPositionByV3(Vector3.New(goTrans.position.x, y, goTrans.position.z))
    end
    local v = _GetV3(self.longTapCatGo)
    v.z = 0
    self.Node.transform.position = isShow and v or Vector3.New(9999, 9999, 0)
end

