---@param isStart boolean
function CatHouseEntry:SetLongTapSignShowState(isStart)
    ----长按状态显示
    self.isMoving = true
    if self.longTapCatGo and isStart then
        self.longTapCatGo.Env:StopTapAction()
        ---再显示长按ui的逻辑
        kTool.SetActive(self.CatGrab.gameObject, true)
        kTool.SetActive(self.Node.gameObject, true)
        self:SetLongTapSignPos(true, 0.1)
    end
end
