---Update
function CatHouseEntry:Update()
    ---玩家回合未开始 不用执行逻辑
    if not self.booleanUpdateRunning then
        return
    end
    if not IsNull(self.mCamera) then
        --- 点击 监听
        if self.touchEventDetectionUtils then
            self.touchEventDetectionUtils:Detection()
        end
        if self.isMoving then
            ---表示按住拖动了
            self:OnMoveEvent()
        end
    end
end

function CatHouseEntry:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self:UnRegRedPoint()
        CatHouseMgr:GetInstance():Delete()
        ---清理工作
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

---FreshBtnCultivationAni
---刷新培育按钮动画
function CatHouseEntry:FreshBtnCultivationAni()
    ---@type CatHouseComponent
    local component = GameUtils.CreateEntityWithComponent(Constants.CatHouseEntityId, ECSComponentType.Constants.CatHouseComponent)
    local catHouseHomeDojo = component:GetCatHouseHomeDojo()
    local deliveryList = catHouseHomeDojo.deliveryList
    local hash = FreeHash
    for i, v in ipairs(deliveryList) do
        if checkNumber(v.status) == ConstantsCatHouse.CatCultivationType.Hatching then
            hash = checkNumber(v.remainTime) > 0 and CultivationHash or HatchHash
            break
        end
    end
    kTool.SetActive(self.ImgDot.gameObject, hash ~= FreeHash)
    self.Container:Play(hash)
end

function CatHouseEntry:RegRedPoint()
    GameUtils.BindRedPoint(Constants.RedPointConst.CatHouseCultivation, self.BtnCultivation, true)
    GameUtils.BindRedPoint(Constants.RedPointConst.CatHouseExplore, self.FlyBtnNode3, true)
end

function CatHouseEntry:UnRegRedPoint()
    GameUtils.RemoveRedPointCallBack(Constants.RedPointConst.CatHouseCultivation)
    GameUtils.RemoveRedPointCallBack(Constants.RedPointConst.CatHouseExplore)
end

function CatHouseEntry:InitListener()
    SetButtonAction(self.FlyBtnNode3, function()
        if CatHouseExploreMgr then
            CatHouseExploreMgr:CatHouseExploreEntry()
        end
    end)
end

return CatHouseEntry